import sys
import math

def main():
    input = sys.stdin.read
    data = input().strip().split()
    n, m, k = int(data[0]), int(data[1]), int(data[2])

    def lcm(x, y):
        return (x * y) // math.gcd(x, y)

    nm = lcm(n, m)

    def f(v):
        return v // n + v // m - 2 * (v // nm)

    ok = 0
    ng = 10**18  # A large number to ensure the binary search works correctly

    while abs(ok - ng) > 1:
        mid = (ok + ng) // 2
        if f(mid) < k:
            ok = mid
        else:
            ng = mid

    print(ok + 1)
